"use client"

import { type ReactNode, useEffect, useMemo, useState } from "react"

import { EinkContext } from "./einkContext"
import { createEinkEngine, type EinkEngine } from "./engine"
import type { EinkIntensity } from "./types"
import { usePrefersReducedMotion } from "./usePrefersReducedMotion"

export type EinkProviderProps = {
  children: ReactNode
  defaultIntensity?: EinkIntensity
}

export function EinkProvider({
  children,
  defaultIntensity = "full",
}: EinkProviderProps) {
  const [engine] = useState<EinkEngine>(createEinkEngine)
  const [intensity, setIntensity] = useState<EinkIntensity>(defaultIntensity)
  const isReducedMotion = usePrefersReducedMotion()
  const effectiveIntensity = isReducedMotion ? "off" : intensity

  useEffect(() => {
    engine.mount(document.documentElement)
    return () => engine.unmount()
  }, [engine])

  useEffect(() => {
    engine.setIntensity(effectiveIntensity)
  }, [engine, effectiveIntensity])

  const value = useMemo(
    () => ({ engine, intensity: effectiveIntensity, isReducedMotion, setIntensity }),
    [engine, effectiveIntensity, isReducedMotion]
  )

  return <EinkContext value={value}>{children}</EinkContext>
}

import type { BayerMatrixSize } from "./types"

function readBayer2(x: number, y: number): number {
  const value = (Math.floor(x) * 0.5 + Math.floor(y) * Math.floor(y) * 0.75) % 1
  return value < 0 ? value + 1 : value
}

function readBayer4(x: number, y: number): number {
  return readBayer2(x * 0.5, y * 0.5) * 0.25 + readBayer2(x, y)
}

function readBayer8(x: number, y: number): number {
  return readBayer4(x * 0.5, y * 0.5) * 0.25 + readBayer2(x, y)
}

const BAYER_READERS: Record<BayerMatrixSize, (x: number, y: number) => number> = {
  4: readBayer4,
  8: readBayer8,
}

export function readBayerThreshold(
  x: number,
  y: number,
  size: BayerMatrixSize
): number {
  return BAYER_READERS[size](x, y)
}

import { readBayerThreshold } from "./bayer"
import { type DitherRequest, readSeedOffset } from "./ditherRenderer"
import type { InkPalette } from "./types"

let sampleCanvas: HTMLCanvasElement | null = null

function readSampleContext(width: number, height: number) {
  sampleCanvas ??= document.createElement("canvas")
  sampleCanvas.width = width
  sampleCanvas.height = height
  return sampleCanvas.getContext("2d", { willReadFrequently: true })
}

export function ditherOnCpu(
  request: DitherRequest,
  inks: InkPalette
): ImageData | null {
  const { width, height, source, matrixSize, contrast } = request
  const context = readSampleContext(width, height)
  if (!context) {
    return null
  }
  context.drawImage(source, 0, 0, width, height)
  const image = context.getImageData(0, 0, width, height)
  const [offsetX, offsetY] = readSeedOffset(request.seed)
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const offset = (y * width + x) * 4
      const luminance =
        (image.data[offset] * 0.2126 +
          image.data[offset + 1] * 0.7152 +
          image.data[offset + 2] * 0.0722) /
        255
      const contrasted = Math.min(1, Math.max(0, (luminance - 0.5) * contrast + 0.5))
      const threshold = readBayerThreshold(x + offsetX, y + offsetY, matrixSize)
      const ink = inks[Math.min(3, Math.max(0, Math.floor(contrasted * 3 + threshold)))]
      image.data[offset] = ink[0]
      image.data[offset + 1] = ink[1]
      image.data[offset + 2] = ink[2]
      image.data[offset + 3] = 255
    }
  }
  return image
}

import { compileProgram, createFullscreenQuad, flattenInks } from "./glProgram"
import { DITHER_FRAGMENT_SHADER, FULLSCREEN_VERTEX_SHADER } from "./shaders"
import type { BayerMatrixSize, InkPalette } from "./types"

export type DitherSource = HTMLImageElement | HTMLCanvasElement | ImageBitmap

export type DitherRequest = {
  source: DitherSource
  width: number
  height: number
  matrixSize: BayerMatrixSize
  contrast: number
  seed: number
}

export type DitherRenderer = {
  render: (request: DitherRequest, inks: InkPalette) => ImageData | null
}

const SEED_OFFSETS = [
  [0, 0],
  [1, 2],
  [3, 1],
  [2, 3],
  [5, 6],
  [7, 4],
] as const

export function readSeedOffset(seed: number): readonly [number, number] {
  return SEED_OFFSETS[Math.abs(Math.floor(seed)) % SEED_OFFSETS.length]
}

export function createDitherRenderer(
  gl: WebGL2RenderingContext
): DitherRenderer | null {
  const program = compileProgram(gl, FULLSCREEN_VERTEX_SHADER, DITHER_FRAGMENT_SHADER)
  const quad = createFullscreenQuad(gl)
  const framebuffer = gl.createFramebuffer()
  const target = gl.createTexture()
  if (!program || !quad || !framebuffer || !target) {
    return null
  }
  const imageLocation = gl.getUniformLocation(program, "uImage")
  const inksLocation = gl.getUniformLocation(program, "uInks")
  const matrixLocation = gl.getUniformLocation(program, "uMatrixSize")
  const seedLocation = gl.getUniformLocation(program, "uSeedOffset")
  const contrastLocation = gl.getUniformLocation(program, "uContrast")
  const sourceTextures = new WeakMap<DitherSource, WebGLTexture>()

  function readSourceTexture(source: DitherSource): WebGLTexture | null {
    const cached = sourceTextures.get(source)
    if (cached) {
      return cached
    }
    const texture = gl.createTexture()
    if (!texture) {
      return null
    }
    gl.bindTexture(gl.TEXTURE_2D, texture)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source)
    sourceTextures.set(source, texture)
    return texture
  }

  function render(request: DitherRequest, inks: InkPalette): ImageData | null {
    const sourceTexture = readSourceTexture(request.source)
    if (!sourceTexture) {
      return null
    }
    const { width, height } = request
    gl.bindTexture(gl.TEXTURE_2D, target)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null)
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, target, 0)
    gl.viewport(0, 0, width, height)
    gl.disable(gl.SCISSOR_TEST)
    gl.useProgram(program)
    gl.bindVertexArray(quad)
    gl.activeTexture(gl.TEXTURE0)
    gl.bindTexture(gl.TEXTURE_2D, sourceTexture)
    gl.uniform1i(imageLocation, 0)
    gl.uniform3fv(inksLocation, flattenInks(inks))
    gl.uniform1i(matrixLocation, request.matrixSize)
    gl.uniform2fv(seedLocation, readSeedOffset(request.seed))
    gl.uniform1f(contrastLocation, request.contrast)
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
    const pixels = new Uint8ClampedArray(width * height * 4)
    gl.readPixels(0, 0, width, height, gl.RGBA, gl.UNSIGNED_BYTE, pixels)
    gl.bindVertexArray(null)
    gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight)
    return new ImageData(pixels, width, height)
  }

  return { render }
}

import {
  createDitherRenderer,
  type DitherRenderer,
  type DitherRequest,
} from "./ditherRenderer"
import { createGhostLayer, type GhostLayer } from "./ghostLayer"
import { INTENSITY_SETTINGS, type IntensitySetting } from "./intensitySettings"
import { observeTheme } from "./observeTheme"
import { createOverlayCanvas } from "./overlayCanvas"
import {
  createOverlayRenderer,
  type OverlayDraw,
  type OverlayRenderer,
} from "./overlayRenderer"
import { PHASE_SHADER_MODES } from "./phaseStyles"
import { areInksEqual, readFps, readInks, readPixel } from "./readTokens"
import { readElementRect, readViewportRect } from "./rects"
import { startRefreshJobs, stepRefreshJobs } from "./refreshScheduler"
import {
  FULL_REFRESH_INTERVAL,
  REFRESH_EFFECTS,
  type RefreshScope,
} from "./refreshSequences"
import type {
  EinkIntensity,
  InkPalette,
  Rect,
  RefreshJob,
  RefreshKind,
  RefreshRequest,
} from "./types"

export type EinkEngine = {
  mount: (root: Element) => void
  unmount: () => void
  requestRefresh: (element: Element, kind: RefreshKind) => void
  requestRefreshRect: (rect: Rect, kind: RefreshKind) => void
  captureGhost: (element: Element) => void
  setIntensity: (intensity: EinkIntensity) => void
  readFps: () => number
  readInks: () => InkPalette | null
  subscribeInks: (listener: () => void) => () => void
  renderDither: (request: DitherRequest) => ImageData | null
}

type EngineSurface = {
  root: Element
  canvas: HTMLCanvasElement
  gl: WebGL2RenderingContext | null
  overlay: OverlayRenderer | null
  dither: DitherRenderer | null
  ghostLayer: GhostLayer
  stopObservingTheme: () => void
}

const SCOPE_RECTS: Record<RefreshScope, (rect: Rect) => Rect> = {
  rect: (rect) => rect,
  viewport: () => readViewportRect(),
}

function toOverlayDraws(
  draws: ReturnType<typeof stepRefreshJobs>["draws"],
  setting: IntensitySetting,
  seed: number
): OverlayDraw[] {
  return draws.flatMap(({ job, phase }) => {
    const mode = PHASE_SHADER_MODES[phase]
    return mode === null
      ? []
      : [
          {
            rect: job.rect,
            mode,
            coverage: setting.coverage * REFRESH_EFFECTS[job.kind].coverage,
            seed,
          },
        ]
  })
}

function createSurface(root: Element, onThemeChange: () => void): EngineSurface {
  const canvas = createOverlayCanvas()
  const gl = canvas.getContext("webgl2", {
    alpha: true,
    antialias: false,
    premultipliedAlpha: false,
  })
  return {
    root,
    canvas,
    gl,
    overlay: gl ? createOverlayRenderer(gl) : null,
    dither: gl ? createDitherRenderer(gl) : null,
    ghostLayer: createGhostLayer(),
    stopObservingTheme: observeTheme(onThemeChange),
  }
}

function destroySurface(surface: EngineSurface) {
  surface.stopObservingTheme()
  surface.ghostLayer.destroy()
  surface.gl?.getExtension("WEBGL_lose_context")?.loseContext()
  surface.canvas.remove()
}

export function createEinkEngine(): EinkEngine {
  const inkListeners = new Set<() => void>()
  let surface: EngineSurface | null = null
  let inks: InkPalette | null = null
  let fps = 12
  let pixel = 2
  let setting = INTENSITY_SETTINGS.full
  let pending: RefreshRequest[] = []
  let jobs: RefreshJob[] = []
  let ghostedThisFrame = new Set<Element>()
  let countedRefreshes = 0
  let frameHandle = 0
  let lastFrameAt = 0

  function resizeOverlay() {
    surface?.overlay?.resize(
      Math.ceil(window.innerWidth / pixel),
      Math.ceil(window.innerHeight / pixel)
    )
  }

  function runFrame() {
    jobs = [...jobs, ...startRefreshJobs(pending)]
    pending = []
    ghostedThisFrame = new Set()
    const frame = stepRefreshJobs(jobs)
    jobs = frame.remaining
    if (!surface || !inks) {
      return
    }
    surface.overlay?.draw(
      toOverlayDraws(frame.draws, setting, Math.random()),
      inks,
      pixel
    )
    for (const job of frame.finished) {
      if (REFRESH_EFFECTS[job.kind].clearsGhosts) {
        surface.ghostLayer.clearWithin(job.rect)
      }
    }
  }

  function loop(now: number) {
    frameHandle = 0
    if (now - lastFrameAt >= 1000 / fps - 1) {
      lastFrameAt = now
      runFrame()
    }
    if (jobs.length > 0 || pending.length > 0) {
      frameHandle = requestAnimationFrame(loop)
    }
  }

  function ensureLoop() {
    if (frameHandle === 0) {
      frameHandle = requestAnimationFrame(loop)
    }
  }

  function requestRefreshRect(rect: Rect, kind: RefreshKind) {
    if (!surface || !setting.isActive) {
      return
    }
    const effect = REFRESH_EFFECTS[kind]
    pending.push({ rect: SCOPE_RECTS[effect.scope](rect), kind })
    if (effect.countsTowardFull) {
      countedRefreshes += 1
    }
    if (countedRefreshes >= FULL_REFRESH_INTERVAL) {
      countedRefreshes = 0
      pending.push({ rect: readViewportRect(), kind: "full" })
    }
    ensureLoop()
  }

  function captureGhost(element: Element) {
    if (!surface || !setting.isActive || ghostedThisFrame.has(element)) {
      return
    }
    ghostedThisFrame.add(element)
    surface.ghostLayer.capture(element, setting.ghostOpacity)
  }

  function requestRefresh(element: Element, kind: RefreshKind) {
    if (REFRESH_EFFECTS[kind].leavesGhost) {
      captureGhost(element)
    }
    requestRefreshRect(readElementRect(element), kind)
  }

  function cancelRefreshes() {
    pending = []
    jobs = []
    surface?.overlay?.clear()
    surface?.ghostLayer.clearAll()
  }

  function setIntensity(intensity: EinkIntensity) {
    setting = INTENSITY_SETTINGS[intensity]
    if (!setting.isActive) {
      cancelRefreshes()
    }
  }

  function syncTheme() {
    if (!surface) {
      return
    }
    const nextInks = readInks(surface.root)
    fps = readFps(surface.root)
    const nextPixel = readPixel(surface.root)
    if (nextPixel !== pixel) {
      pixel = nextPixel
      resizeOverlay()
    }
    if (inks && areInksEqual(nextInks, inks)) {
      return
    }
    inks = nextInks
    inkListeners.forEach((listener) => listener())
    requestRefreshRect(readViewportRect(), "full")
  }

  function mount(root: Element) {
    if (surface) {
      return
    }
    surface = createSurface(root, syncTheme)
    inks = readInks(root)
    fps = readFps(root)
    pixel = readPixel(root)
    resizeOverlay()
    window.addEventListener("resize", resizeOverlay)
    inkListeners.forEach((listener) => listener())
  }

  function unmount() {
    if (!surface) {
      return
    }
    cancelAnimationFrame(frameHandle)
    frameHandle = 0
    cancelRefreshes()
    window.removeEventListener("resize", resizeOverlay)
    destroySurface(surface)
    surface = null
    inks = null
    inkListeners.forEach((listener) => listener())
  }

  function subscribeInks(listener: () => void) {
    inkListeners.add(listener)
    return () => {
      inkListeners.delete(listener)
    }
  }

  function renderDither(request: DitherRequest) {
    if (!surface?.dither || !inks) {
      return null
    }
    return surface.dither.render(request, inks)
  }

  return {
    mount,
    unmount,
    requestRefresh,
    requestRefreshRect,
    captureGhost,
    setIntensity,
    readFps: () => fps,
    readInks: () => inks,
    subscribeInks,
    renderDither,
  }
}

import { doRectsOverlap, readElementRect } from "./rects"
import type { Rect } from "./types"

const MAX_GHOSTS = 48

type Ghost = {
  node: HTMLElement
  rect: Rect
}

export type GhostLayer = {
  capture: (element: Element, opacity: number) => void
  clearWithin: (rect: Rect) => void
  clearAll: () => void
  destroy: () => void
}

function copyCanvases(source: Element, clone: Element) {
  const sourceCanvases = source.querySelectorAll("canvas")
  const cloneCanvases = clone.querySelectorAll("canvas")
  sourceCanvases.forEach((canvas, index) => {
    const target = cloneCanvases[index]
    const context = target?.getContext("2d")
    if (context && canvas.width > 0 && canvas.height > 0) {
      context.drawImage(canvas, 0, 0)
    }
  })
}

function buildGhostNode(element: Element, rect: Rect, opacity: number): HTMLElement {
  const clone = element.cloneNode(true)
  const wrapper = document.createElement("div")
  wrapper.className = "eink-ghost"
  wrapper.setAttribute("aria-hidden", "true")
  wrapper.inert = true
  Object.assign(wrapper.style, {
    position: "fixed",
    left: `${rect.x}px`,
    top: `${rect.y}px`,
    width: `${rect.width}px`,
    height: `${rect.height}px`,
    opacity: String(opacity),
    overflow: "hidden",
  })
  if (clone instanceof HTMLElement) {
    clone.removeAttribute("id")
    clone.querySelectorAll("[id]").forEach((node) => node.removeAttribute("id"))
    Object.assign(clone.style, {
      position: "absolute",
      left: "0px",
      top: "0px",
      right: "auto",
      bottom: "auto",
      margin: "0px",
      transform: "none",
      width: `${rect.width}px`,
      height: `${rect.height}px`,
    })
    copyCanvases(element, clone)
    wrapper.append(clone)
  }
  return wrapper
}

export function createGhostLayer(): GhostLayer {
  const layer = document.createElement("div")
  layer.setAttribute("aria-hidden", "true")
  layer.dataset.einkLayer = "ghosts"
  Object.assign(layer.style, {
    position: "fixed",
    inset: "0px",
    pointerEvents: "none",
    zIndex: "40",
    overflow: "hidden",
  })
  document.body.append(layer)
  let ghosts: Ghost[] = []

  function capture(element: Element, opacity: number) {
    const rect = readElementRect(element)
    if (rect.width === 0 || rect.height === 0 || opacity <= 0) {
      return
    }
    const node = buildGhostNode(element, rect, opacity)
    layer.append(node)
    ghosts.push({ node, rect })
    while (ghosts.length > MAX_GHOSTS) {
      ghosts.shift()?.node.remove()
    }
  }

  function clearWithin(rect: Rect) {
    ghosts = ghosts.filter((ghost) => {
      const isCovered = doRectsOverlap(ghost.rect, rect)
      if (isCovered) {
        ghost.node.remove()
      }
      return !isCovered
    })
  }

  function clearAll() {
    ghosts.forEach((ghost) => ghost.node.remove())
    ghosts = []
  }

  function destroy() {
    clearAll()
    layer.remove()
  }

  return { capture, clearWithin, clearAll, destroy }
}

import type { InkPalette } from "./types"

function compileShader(
  gl: WebGL2RenderingContext,
  type: number,
  source: string
): WebGLShader | null {
  const shader = gl.createShader(type)
  if (!shader) {
    return null
  }
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.error(gl.getShaderInfoLog(shader))
    gl.deleteShader(shader)
    return null
  }
  return shader
}

export function compileProgram(
  gl: WebGL2RenderingContext,
  vertexSource: string,
  fragmentSource: string
): WebGLProgram | null {
  const vertexShader = compileShader(gl, gl.VERTEX_SHADER, vertexSource)
  const fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, fragmentSource)
  const program = gl.createProgram()
  if (!vertexShader || !fragmentShader || !program) {
    return null
  }
  gl.attachShader(program, vertexShader)
  gl.attachShader(program, fragmentShader)
  gl.bindAttribLocation(program, 0, "aPosition")
  gl.linkProgram(program)
  gl.deleteShader(vertexShader)
  gl.deleteShader(fragmentShader)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(program))
    gl.deleteProgram(program)
    return null
  }
  return program
}

export function createFullscreenQuad(
  gl: WebGL2RenderingContext
): WebGLVertexArrayObject | null {
  const vertexArray = gl.createVertexArray()
  const buffer = gl.createBuffer()
  if (!vertexArray || !buffer) {
    return null
  }
  gl.bindVertexArray(vertexArray)
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
    gl.STATIC_DRAW
  )
  gl.enableVertexAttribArray(0)
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
  gl.bindVertexArray(null)
  return vertexArray
}

export function flattenInks(inks: InkPalette): Float32Array {
  return new Float32Array(inks.flatMap((ink) => ink.map((channel) => channel / 255)))
}

import type { EinkIntensity } from "./types"

export type IntensitySetting = {
  isActive: boolean
  coverage: number
  ghostOpacity: number
}

export const INTENSITY_SETTINGS: Record<EinkIntensity, IntensitySetting> = {
  off: { isActive: false, coverage: 0, ghostOpacity: 0 },
  subtle: { isActive: true, coverage: 0.5, ghostOpacity: 0.22 },
  full: { isActive: true, coverage: 1, ghostOpacity: 0.45 },
}

export const EINK_INTENSITIES = Object.keys(
  INTENSITY_SETTINGS
) as readonly EinkIntensity[]

const THEME_ATTRIBUTES = ["class", "data-theme", "style"]

export function observeTheme(onChange: () => void): () => void {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: THEME_ATTRIBUTES,
  })
  return () => observer.disconnect()
}

export function createOverlayCanvas(): HTMLCanvasElement {
  const canvas = document.createElement("canvas")
  canvas.setAttribute("aria-hidden", "true")
  canvas.dataset.einkLayer = "overlay"
  Object.assign(canvas.style, {
    position: "fixed",
    inset: "0px",
    width: "100vw",
    height: "100vh",
    pointerEvents: "none",
    zIndex: "2147483000",
    imageRendering: "pixelated",
  })
  document.body.append(canvas)
  return canvas
}

import { compileProgram, createFullscreenQuad, flattenInks } from "./glProgram"
import { FULLSCREEN_VERTEX_SHADER, OVERLAY_FRAGMENT_SHADER } from "./shaders"
import type { InkPalette, Rect } from "./types"

export type OverlayDraw = {
  rect: Rect
  mode: number
  coverage: number
  seed: number
}

export type OverlayRenderer = {
  resize: (width: number, height: number) => void
  clear: () => void
  draw: (draws: readonly OverlayDraw[], inks: InkPalette, pixel: number) => void
}

export function createOverlayRenderer(
  gl: WebGL2RenderingContext
): OverlayRenderer | null {
  const program = compileProgram(gl, FULLSCREEN_VERTEX_SHADER, OVERLAY_FRAGMENT_SHADER)
  const quad = createFullscreenQuad(gl)
  if (!program || !quad) {
    return null
  }
  const inksLocation = gl.getUniformLocation(program, "uInks")
  const modeLocation = gl.getUniformLocation(program, "uMode")
  const coverageLocation = gl.getUniformLocation(program, "uCoverage")
  const seedLocation = gl.getUniformLocation(program, "uSeed")

  function clear() {
    gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    gl.disable(gl.SCISSOR_TEST)
    gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight)
    gl.clearColor(0, 0, 0, 0)
    gl.clear(gl.COLOR_BUFFER_BIT)
  }

  function resize(width: number, height: number) {
    gl.canvas.width = width
    gl.canvas.height = height
    clear()
  }

  function draw(draws: readonly OverlayDraw[], inks: InkPalette, pixel: number) {
    clear()
    if (draws.length === 0) {
      return
    }
    gl.useProgram(program)
    gl.bindVertexArray(quad)
    gl.uniform3fv(inksLocation, flattenInks(inks))
    gl.enable(gl.SCISSOR_TEST)
    const bufferHeight = gl.drawingBufferHeight
    for (const { rect, mode, coverage, seed } of draws) {
      const left = Math.floor(rect.x / pixel)
      const top = Math.floor(rect.y / pixel)
      const right = Math.ceil((rect.x + rect.width) / pixel)
      const bottom = Math.ceil((rect.y + rect.height) / pixel)
      gl.scissor(left, bufferHeight - bottom, right - left, bottom - top)
      gl.uniform1i(modeLocation, mode)
      gl.uniform1f(coverageLocation, coverage)
      gl.uniform1f(seedLocation, seed)
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
    }
    gl.disable(gl.SCISSOR_TEST)
    gl.bindVertexArray(null)
  }

  return { resize, clear, draw }
}

import type { InkPalette, Rgb } from "./types"

const INK_TOKENS = ["--ink-0", "--ink-1", "--ink-2", "--ink-3"] as const

const DEFAULT_FPS = 12
const DEFAULT_PIXEL = 2

let colorProbe: CanvasRenderingContext2D | null = null

function readColorProbe(): CanvasRenderingContext2D | null {
  if (colorProbe) {
    return colorProbe
  }
  const canvas = document.createElement("canvas")
  canvas.width = 1
  canvas.height = 1
  colorProbe = canvas.getContext("2d", { willReadFrequently: true })
  return colorProbe
}

export function parseCssColor(value: string): Rgb {
  const probe = readColorProbe()
  if (!probe || value.trim() === "") {
    return [0, 0, 0]
  }
  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = "#000000"
  probe.fillStyle = value.trim()
  probe.fillRect(0, 0, 1, 1)
  const [red, green, blue] = probe.getImageData(0, 0, 1, 1).data
  return [red, green, blue]
}

function readToken(root: Element, token: string): string {
  return getComputedStyle(root).getPropertyValue(token).trim()
}

export function readInks(root: Element): InkPalette {
  const [ink0, ink1, ink2, ink3] = INK_TOKENS.map((token) =>
    parseCssColor(readToken(root, token))
  )
  return [ink0, ink1, ink2, ink3]
}

function readPositiveNumber(raw: string, fallback: number): number {
  const parsed = Number.parseFloat(raw)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback
}

export function readFps(root: Element): number {
  return readPositiveNumber(readToken(root, "--eink-fps"), DEFAULT_FPS)
}

export function readPixel(root: Element): number {
  return readPositiveNumber(readToken(root, "--pixel"), DEFAULT_PIXEL)
}

export function areInksEqual(first: InkPalette, second: InkPalette): boolean {
  return first.every((ink, inkIndex) =>
    ink.every((channel, channelIndex) => channel === second[inkIndex][channelIndex])
  )
}

import { REFRESH_EFFECTS } from "./refreshSequences"
import type { Rect, RefreshRequest } from "./types"

export function readElementRect(element: Element): Rect {
  const bounds = element.getBoundingClientRect()
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.width,
    height: bounds.height,
  }
}

export function readViewportRect(): Rect {
  return { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight }
}

export function doRectsOverlap(first: Rect, second: Rect): boolean {
  return (
    first.x < second.x + second.width &&
    second.x < first.x + first.width &&
    first.y < second.y + second.height &&
    second.y < first.y + first.height
  )
}

export function uniteRects(first: Rect, second: Rect): Rect {
  const left = Math.min(first.x, second.x)
  const top = Math.min(first.y, second.y)
  const right = Math.max(first.x + first.width, second.x + second.width)
  const bottom = Math.max(first.y + first.height, second.y + second.height)
  return { x: left, y: top, width: right - left, height: bottom - top }
}

export function translateRect(rect: Rect, dx: number, dy: number): Rect {
  return { ...rect, x: rect.x + dx, y: rect.y + dy }
}

function mergeTwoRequests(
  first: RefreshRequest,
  second: RefreshRequest
): RefreshRequest {
  const isFirstStronger =
    REFRESH_EFFECTS[first.kind].rank >= REFRESH_EFFECTS[second.kind].rank
  return {
    rect: uniteRects(first.rect, second.rect),
    kind: isFirstStronger ? first.kind : second.kind,
  }
}

export function mergeOverlappingRequests(
  requests: readonly RefreshRequest[]
): RefreshRequest[] {
  const merged: RefreshRequest[] = []
  for (const request of requests) {
    let current = request
    let overlapIndex = merged.findIndex((existing) =>
      doRectsOverlap(existing.rect, current.rect)
    )
    while (overlapIndex !== -1) {
      current = mergeTwoRequests(merged[overlapIndex], current)
      merged.splice(overlapIndex, 1)
      overlapIndex = merged.findIndex((existing) =>
        doRectsOverlap(existing.rect, current.rect)
      )
    }
    merged.push(current)
  }
  return merged
}

import { mergeOverlappingRequests } from "./rects"
import { REFRESH_SEQUENCES } from "./refreshSequences"
import type { RefreshJob, RefreshPhase, RefreshRequest } from "./types"

export type PhaseDraw = {
  job: RefreshJob
  phase: RefreshPhase
}

export type RefreshFrame = {
  draws: PhaseDraw[]
  finished: RefreshJob[]
  remaining: RefreshJob[]
}

export function startRefreshJobs(
  pending: readonly RefreshRequest[]
): RefreshJob[] {
  return mergeOverlappingRequests(pending).map((request) => ({
    ...request,
    phaseIndex: 0,
  }))
}

export function stepRefreshJobs(jobs: readonly RefreshJob[]): RefreshFrame {
  const frame: RefreshFrame = { draws: [], finished: [], remaining: [] }
  for (const job of jobs) {
    const sequence = REFRESH_SEQUENCES[job.kind]
    frame.draws.push({ job, phase: sequence[job.phaseIndex] })
    const next = { ...job, phaseIndex: job.phaseIndex + 1 }
    const bucket = next.phaseIndex >= sequence.length ? frame.finished : frame.remaining
    bucket.push(next)
  }
  return frame
}

export const FULLSCREEN_VERTEX_SHADER = `#version 300 es
in vec2 aPosition;
out vec2 vUv;
void main() {
  vUv = aPosition * 0.5 + 0.5;
  gl_Position = vec4(aPosition, 0.0, 1.0);
}
`

const BAYER_GLSL = `
float readBayer2(vec2 a) {
  a = floor(a);
  return fract(a.x * 0.5 + a.y * a.y * 0.75);
}
float readBayer4(vec2 a) {
  return readBayer2(0.5 * a) * 0.25 + readBayer2(a);
}
float readBayer8(vec2 a) {
  return readBayer4(0.5 * a) * 0.25 + readBayer2(a);
}
`

export const OVERLAY_FRAGMENT_SHADER = `#version 300 es
precision highp float;
uniform vec3 uInks[4];
uniform int uMode;
uniform float uCoverage;
uniform float uSeed;
out vec4 outColor;
${BAYER_GLSL}
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21) + uSeed);
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
void main() {
  vec2 cell = floor(gl_FragCoord.xy);
  if (readBayer4(cell) >= uCoverage) {
    discard;
  }
  vec3 color = uInks[0];
  if (uMode == 1) {
    color = uInks[3];
  } else if (uMode == 2) {
    float level = hash(floor(cell / 2.0)) * 3.0 + readBayer4(cell);
    color = uInks[int(clamp(floor(level), 0.0, 3.0))];
  }
  outColor = vec4(color, 1.0);
}
`

export const DITHER_FRAGMENT_SHADER = `#version 300 es
precision highp float;
uniform sampler2D uImage;
uniform vec3 uInks[4];
uniform int uMatrixSize;
uniform vec2 uSeedOffset;
uniform float uContrast;
in vec2 vUv;
out vec4 outColor;
${BAYER_GLSL}
void main() {
  vec3 source = texture(uImage, vUv).rgb;
  float luminance = dot(source, vec3(0.2126, 0.7152, 0.0722));
  luminance = clamp((luminance - 0.5) * uContrast + 0.5, 0.0, 1.0);
  vec2 cell = floor(gl_FragCoord.xy) + uSeedOffset;
  float threshold = uMatrixSize == 8 ? readBayer8(cell) : readBayer4(cell);
  int index = int(clamp(floor(luminance * 3.0 + threshold), 0.0, 3.0));
  outColor = vec4(uInks[index], 1.0);
}
`

